window.CONTENT_DHIKR=[{"ar":"سُبْحَانَ اللَّهِ وَبِحَمْدِهِ","tr":"Subḥān Allāh wa bi-ḥamdih","de":"Preis sei Allah und Lob Ihm.","reward":"Der Gesandte Allahs ﷺ sagte: Wer an einem Tag hundertmal sagt: Preis sei Allah und Lob Ihm, dessen Verfehlungen werden getilgt, selbst wenn sie wie der Schaum des Meeres wären. (Ṣaḥīḥ al-Buḫārī, Nr. 6405)"},{"ar":"الْحَمْدُ لِلَّهِ","tr":"Al-ḥamdu lillāh","de":"Alles Lob gebührt Allah.","reward":"Der Gesandte Allahs ﷺ sagte: Die Reinheit ist die Hälfte des Glaubens, und al-Hamdu lillah füllt die Waagschale. (Ṣaḥīḥ Muslim, Nr. 223)"},{"ar":"سُبْحَانَ اللَّهِ، وَالْحَمْدُ لِلَّهِ، وَلَا إِلَهَ إِلَّا اللَّهُ، وَاللَّهُ أَكْبَرُ","tr":"Subḥān Allāh, wal-ḥamdu lillāh, wa lā ilāha illallāh, wallāhu akbar","de":"Preis sei Allah, alles Lob gebührt Allah, es gibt keinen Gott außer Allah und Allah ist größer.","reward":"Der Gesandte Allahs ﷺ sagte: Dass ich sage: Subhan Allah, wal-hamdu lillah, wa la ilaha illallah, wallahu akbar, ist mir lieber als alles, worüber die Sonne aufgeht. (Ṣaḥīḥ Muslim, Nr. 2695)"},{"ar":"لَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ","tr":"Lā ḥawla wa lā quwwata illā billāh","de":"Es gibt weder Macht noch Kraft außer durch Allah.","reward":"Der Gesandte Allahs ﷺ sagte zu Abu Musa al-Ash'ari: Soll ich dich nicht auf einen Schatz aus den Schätzen des Paradieses hinweisen? Ich sagte: Doch, o Gesandter Allahs. Er sagte: La hawla wa la quwwata illa billah. (Ṣaḥīḥ al-Buḫārī, Nr. 4205)"},{"ar":"أَسْتَغْفِرُ اللَّهَ","tr":"Astaghfirullāh","de":"Ich bitte Allah um Vergebung.","reward":"Der Gesandte Allahs ﷺ sagte: Bei Allah, ich bitte Allah gewiss täglich mehr als siebzigmal um Vergebung und wende mich Ihm reumütig zu. (Ṣaḥīḥ al-Buḫārī, Nr. 6307)"},{"ar":"قُلْ هُوَ اللَّهُ أَحَدٌ ۝ قُلْ أَعُوذُ بِرَبِّ الْفَلَقِ ۝ قُلْ أَعُوذُ بِرَبِّ النَّاسِ","tr":"Al-Muʿawwiḏāt (Sūrat al-Iḫlāṣ, al-Falaq, an-Nās)","de":"Die drei Schutzsuren (Sure 112, 113, 114)","reward":"Der Gesandte Allahs ﷺ sagte: Sprich Qul huwa Allahu ahad und die beiden Schutzsuren, wenn du den Abend und den Morgen erreichst, dreimal; sie werden dir gegen alles genügen. (Sunan Abī Dāwūd, Nr. 5082; Jāmiʿ at-Tirmiḏī, Nr. 3575)"},{"ar":"لَا إِلَهَ إِلَّا اللَّهُ","tr":"Lā ilāha illallāh","de":"Es gibt keinen Gott außer Allah.","reward":"Der Gesandte Allahs ﷺ sagte: Das beste Gedenken ist: La ilaha illallah, und das beste Bittgebet ist: al-Hamdu lillah. (Jāmiʿ at-Tirmiḏī, Nr. 3383)"},{"ar":"أَسْتَغْفِرُ اللَّهَ وَأَتُوبُ إِلَيْهِ","tr":"Astaghfirullāh wa-atūbu ilayh","de":"Ich bitte Allah um Vergebung und kehre reumütig zu Ihm zurück.","reward":"Der Gesandte Allahs ﷺ sagte: O Menschen, wendet euch reumütig an Allah. Gewiss, ich wende mich an einem Tag hundertmal Ihm reumütig zu. (Ṣaḥīḥ Muslim, Nr. 2702)"},{"ar":"اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ","tr":"Allāhumma ṣalli ʿalā Muḥammad","de":"O Allah, segne Muhammad.","reward":"Der Gesandte Allahs ﷺ sagte: Wer einmal den Segen auf mich spricht, den segnet Allah zehnmal. (Ṣaḥīḥ Muslim, Nr. 408)"},{"ar":"لَا إِلَهَ إِلَّا اللَّهُ وَحْدَهُ لَا شَرِيكَ لَهُ، لَهُ الْمُلْكُ وَلَهُ الْحَمْدُ، وَهُوَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ","tr":"Lā ilāha illallāhu waḥdahū lā šarīka lah, lahul-mulku wa lahul-ḥamdu, wa huwa ʿalā kulli šay'in qadīr","de":"Es gibt keinen Gott außer Allah allein, Er hat keinen Teilhaber. Sein ist die Herrschaft und Sein das Lob, und Er hat über alle Dinge Macht.","reward":"Der Gesandte Allahs ﷺ sagte: Wer dies zehnmal spricht, ist wie jemand, der vier Seelen von den Nachkommen Ismails befreit hat. (Ṣaḥīḥ al-Buḫārī, Nr. 6404; Ṣaḥīḥ Muslim, Nr. 2693)"},{"ar":"لَا إِلَهَ إِلَّا أَنْتَ سُبْحَانَكَ إِنِّي كُنْتُ مِنَ الظَّالِمِينَ","tr":"Lā ilāha illā Anta subḥānaka innī kuntu minaẓ-ẓālimīn","de":"Es gibt keinen Gott außer Dir! Preis sei Dir! Wahrlich, ich gehörte zu den Ungerechten.","reward":"Der Gesandte Allahs ﷺ sagte: Das Bittgebet von Dhu n-Nun, das er im Bauch des Fisches sprach: Kein muslimischer Mann betet jemals damit um eine Sache, ohne dass Allah sie für ihn erhört. (Jāmiʿ at-Tirmiḏī, Nr. 3505)"},{"ar":"رَضِيتُ بِاللَّهِ رَبًّا، وَبِالْإِسْلَامِ دِينًا، وَبِمُحَمَّدٍ نَبِيًّا","tr":"Raḍītu billāhi Rabban, wa bil-Islāmi dīnan, wa bi-Muḥammadin nabiyyā","de":"Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad als Propheten.","reward":"Der Gesandte Allahs ﷺ sagte: Wer sagt: Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad als Gesandten, für den ist das Paradies verpflichtend geworden. (Sunan Abī Dāwūd, Nr. 1529)"},{"ar":"سُبْحَانَ اللَّهِ الْعَظِيمِ وَبِحَمْدِهِ","tr":"Subḥān Allāh al-ʿAẓīm wa bi-ḥamdih","de":"Preis sei Allah, dem Allgewaltigen, und Lob Ihm.","reward":"Der Gesandte Allahs ﷺ sagte: Wer sagt: Preis sei Allah, dem Allgewaltigen, und Lob Ihm, dem wird eine Dattelpalme im Paradies gepflanzt. (Jāmiʿ at-Tirmiḏī, Nr. 3464)"},{"ar":"حَسْبِيَ اللَّهُ لَا إِلَهَ إِلَّا هُوَ عَلَيْهِ تَوَكَّلْتُ وَهُوَ رَبُّ الْعَرْشِ الْعَظِيمِ","tr":"Ḥasbiyallāhu lā ilāha illā Huwa ʿalayhi tawakkaltu wa Huwa Rabbul-ʿaršil-ʿaẓīm","de":"Allah genügt mir. Es gibt keinen Gott außer Ihm. Auf Ihn vertraue ich, und Er ist der Herr des gewaltigen Thrones.","reward":"Überliefert über Abu d-Darda: Wer am Morgen und am Abend siebenmal sagt: Allah genügt mir, es gibt keinen Gott außer Ihm, auf Ihn vertraue ich und Er ist der Herr des gewaltigen Thrones, dem nimmt Allah die Sorgen ab, die ihn bedrücken. (Sunan Abī Dāwūd, Nr. 5081)"}];
window.CONTENT_QUIZ=[{"q":"In welcher Stadt kam der Prophet Muhammad ﷺ zur Welt?","answers":["Mekka al-Mukarrama","Medina al-Munawwara","Die Oase von Taif","Die Stadt Jerusalem"]},{"q":"Wie hieß die leibliche Mutter des Propheten Muhammad ﷺ?","answers":["Amina bint Wahb","Halima as-Sa'diyya","Baraka Umm Ayman","Fatima bint Asad"]},{"q":"Welcher Engel überbrachte dem Propheten Muhammad ﷺ die göttliche Offenbarung?","answers":["Engel Dschibril","Engel Mika'il","Engel Israfil","Engel Azra'il"]},{"q":"Wie hieß die erste Ehefrau des Propheten Muhammad ﷺ?","answers":["Khadidscha bint Chuwailid","Hafsa bint Umar al-Faruq","Sauda bint Zam'a al-Amiriyya","Aischa bint Abi Bakr as-Siddiq"]},{"q":"Wo empfing der Prophet Muhammad ﷺ die allererste Offenbarung des Korans?","answers":["In der Höhle Hira auf dem Berg an-Nur","In der Höhle Thaur südlich von Mekka","Im Vorhof der Kaaba neben dem Brunnen Zamzam","Im Tal von Mina während der Wallfahrt"]},{"q":"Welcher Großvater zog den Propheten Muhammad ﷺ nach dem Tod der Mutter auf?","answers":["Abd al-Muttalib ibn Haschim","Abu Talib ibn Abd al-Muttalib","Az-Zubair ibn Abd al-Muttalib","Al-Harith ibn Abd al-Muttalib"]},{"q":"Welcher enge Gefährte begleitete den Propheten Muhammad ﷺ bei der Hidschra?","answers":["Abu Bakr as-Siddiq","Umar ibn al-Chattab","Uthman ibn Affan","Ali ibn Abi Talib"]},{"q":"In welchem Jahr der christlichen Zeitrechnung fand die Hidschra nach Medina statt?","answers":["Im Jahr 622 nach Christus","Im Jahr 610 nach Christus","Im Jahr 630 nach Christus","Im Jahr 632 nach Christus"]},{"q":"Wie hieß die Amme die den Propheten Muhammad ﷺ in der Wüste stillte?","answers":["Halima as-Sa'diyya","Barakah Umm Ayman","Schaimaa as-Sa'diyya","Fatima bint Asad"]},{"q":"Welchen Beinamen trug der Prophet Muhammad ﷺ bereits vor der Gesandtschaft?","answers":["Al-Amin der Vertrauenswürdige","As-Siddiq der stets Wahrhaftige","Al-Faruq der gerechte Richter","Dhu an-Nurain der Träger zweier Lichter"]},{"q":"Wie hieß die erste große Schlacht zwischen den Muslimen und den Quraisch?","answers":["Die Schlacht von Badr","Die Schlacht von Uhud","Die Grabenschlacht bei Medina","Die Schlacht von Hunain"]},{"q":"Welcher Onkel des Propheten Muhammad ﷺ schützte ihn jahrelang treu in Mekka?","answers":["Abu Talib ibn Abd al-Muttalib","Al-Abbas ibn Abd al-Muttalib","Hamza ibn Abd al-Muttalib","Al-Harith ibn Abd al-Muttalib"]},{"q":"In welchem Lebensjahr befand sich der Prophet Muhammad ﷺ bei Beginn des Prophetentums?","answers":["Im Alter von vierzig Jahren","Im Alter von dreißig Jahren","Im Alter von fünfzig Jahren","Im Alter von zwanzig Jahren"]},{"q":"In welchem Jahr nach der Hidschra erfolgte die friedliche Öffnung Mekkas?","answers":["Im achten Jahr nach der Hidschra","Im sechsten Jahr nach der Hidschra","Im zweiten Jahr nach der Hidschra","Im zehnten Jahr nach der Hidschra"]},{"q":"An welchem Ort wurde der Prophet Muhammad ﷺ nach seinem Ableben beigesetzt?","answers":["Im Zimmer von Aischa in Medina","In der Kaaba von Mekka al-Mukarrama","Auf dem Friedhof al-Baqi in Medina","In der al-Aqsa Moschee in Jerusalem"]},{"q":"Welcher christliche Mönch in Bosra erkannte die Zeichen des Prophetentums?","answers":["Der Mönch Bahira","Der Mönch Sergius","Der Mönch Nestor","Der Gelehrte Kosmas"]},{"q":"In welches Land wanderten verfolgte Muslime aus Mekka zuerst aus?","answers":["Nach Abessinien ins Reich des Negus","In das südarabische Reich Jemen","Nach Oman an den Persischen Golf","In das Stammesgebiet von Bahrain"]},{"q":"Welcher jüdische Stamm beging während der Grabenschlacht Verrat am Vertrag?","answers":["Der Stamm Banu Quraiza","Der Stamm Banu Qainuqa","Der Stamm Banu an-Nadir","Der Stamm Banu Mustaliq"]},{"q":"Welcher Gefährte schlug den Bau eines Schutzgrabens um Medina vor?","answers":["Salman al-Farisi","Ammar ibn Yasir","Bilal al-Habaschi","Suhaib ar-Rumi"]},{"q":"Wer unterschrieb das Abkommen von al-Hudaibiyya aufseiten der Quraisch?","answers":["Suhail ibn Amr","Safwan ibn Umayya","Ikrimah ibn Abi Dschahl","Hakim ibn Hizam"]},{"q":"In welcher Schlacht fiel Hamza ibn Abd al-Muttalib als Märtyrer?","answers":["In der Schlacht von Uhud","In der Schlacht von Badr","In der Schlacht von Hunain","In der Schlacht von Tabuk"]},{"q":"Welcher Verwandte von Khadidscha deutete die erste Offenbarung anhand der Schriften?","answers":["Waraqa ibn Naufal","Zaid ibn Amr ibn Naufal","Umayya ibn Abi as-Salt","Uthman ibn al-Huwairith"]},{"q":"Wer galt zur Zeit des Propheten ﷺ als das Oberhaupt der Heuchler in Medina?","answers":["Abdullah ibn Ubayy ibn Salul","Ka'b ibn al-Aschraf al-Yahudi","Huyayy ibn Achtab an-Nadari","Dhu al-Chuwaisira at-Tamimi"]},{"q":"Welcher Feldzug im Safar 2 n. H. war der erste vom Propheten ﷺ persönlich angeführte?","answers":["Die Ghazwa von al-Abwa oder Waddan","Die Ghazwa von Buwat bei Radwa","Die Ghazwa von Dhu al-Uschaira","Die Ghazwa Safwan bei Badr al-Ula"]},{"q":"Wer wurde vom Propheten ﷺ zum allerersten Gebetsrufer des Islam ernannt?","answers":["Bilal ibn Rabah al-Habaschi","Abu Mahdhura al-Dschumahi","Amr ibn Umm Maktum al-Quraschi","Sa'd ibn A'idh al-Qaraz"]},{"q":"Wer kommandierte die erste Entsendung namens Sariyya Saif al-Bahr im Ramadan 1 n. H.?","answers":["Hamza ibn Abd al-Muttalib","Ubaida ibn al-Harith","Sa'd ibn Abi Waqqas","Zaid ibn Haritha"]},{"q":"Welcher Gefährte überbrachte das Sendschreiben des Propheten ﷺ an Kaiser Heraklios?","answers":["Dihya ibn Chalifa al-Kalbi","Schudscha ibn Wahb al-Asadi","Hatib ibn Abi Balta'a al-Lachmi","Amr ibn Umayya ad-Damri"]},{"q":"Welche zwei großen Stämme verbündeten sich im Jahr 8 n. H. zur Schlacht von Hunain?","answers":["Die Stämme Hawazin und Thaqif","Die Stämme Ghatafan und Sulaim","Die Stämme Kinana und Hudhail","Die Stämme Bakr und Taghlib"]},{"q":"Wer leitete im Auftrag des Propheten ﷺ im Jahr 9 n. H. die erste reine Haddsch-Pilgerfahrt?","answers":["Abu Bakr as-Siddiq","Umar ibn al-Chattab","Ali ibn Abi Talib","Mu'adh ibn Dschabal"]},{"q":"Aus welcher Region stammte die christliche Gesandtschaft die das Abkommen mit Medina schloss?","answers":["Aus dem fruchtbaren Nadschran","Aus dem nördlichen al-Hira","Aus dem syrischen Bosra","Aus dem jemenitischen Sanaa"]}];
window.CONTENT_TEXTS=[{"title":"Die Schlichtung an der Kaaba","text":"Vor Beginn seines Prophetentums beschloss der Stamm der Quraisch, die Kaaba zu renovieren, da sie durch Überschwemmungen baufällig geworden war. Als die Mauern errichtet waren, entstand ein erbitterter Streit: Welcher Clan sollte die Ehre erhalten, den verehrten Schwarzen Stein an seinen Platz zu heben? Mehrere Tage ruhten die Arbeiten, und ein blutiger Konflikt drohte. Schließlich schlug der älteste Ratsherr vor, den ersten Mann entscheiden zu lassen, der das Tor des Heiligtums betritt. Zur Erleichterung aller erschien Muhammad ﷺ, der wegen seiner Aufrichtigkeit geschätzt wurde. Er löste die Krise mit Weitsicht: Er breitete sein Obergewand auf dem Boden aus, legte den Stein in die Mitte und forderte die Anführer aller rivalisierenden Stämme auf, gemeinsam die Ränder des Tuchs anzuheben. Als der Stein an der Mauer ankam, setzte er ﷺ ihn mit den eigenen Händen ein.","question":"Wie verhinderte Muhammad ﷺ, dass sich einer der Stämme bei der Platzierung des Steins benachteiligt fühlte?","options":[{"text":"Er bestimmte den ältesten Ratsherrn dazu, den Stein stellvertretend für alle Clans einzusetzen.","correct":false},{"text":"Er ließ die Stammesführer gemeinsam die Ecken seines ausgebreiteten Gewands anheben, auf dem der Stein lag.","correct":true},{"text":"Er ließ das Los zwischen den Anführern entscheiden, damit das Schicksal gerecht wählte.","correct":false}]},{"title":"Der Prophet ﷺ und der kleine Vogel","text":"Der Prophet Muhammad ﷺ zeichnete sich durch seine feinfühlige Zuneigung zu Kindern aus. Der Gefährte Anas ibn Mālik berichtete, dass der Gesandte Allahs ﷺ ihre Familie oft besuchte. Anas hatte einen kleinen Halbbruder namens Abū ʿUmayr. Der Junge besaß ein winziges Haustier: ein kleines Vögelchen, einen sogenannten Nughayr, an dem er sehr hing. Eines Tages kam der Prophet ﷺ zu Besuch und bemerkte, dass das Kind bedrückt und weinend in einer Ecke saß. Als er ﷺ nach dem Grund fragte, erfuhr er, dass das Vögelchen gestorben war. Anstatt die Gefühle des Kindes abzutun, setzte sich der Gesandte Allahs ﷺ geduldig zu ihm. Er spendete ihm Trost und sprach mit ihm in sanften, heiteren Reimen: „O Abū ʿUmayr, was hat das Vögelchen gemacht?“ Durch diese persönliche Aufmerksamkeit brachte er das traurige Kind wieder zum Lächeln.","question":"Wie reagierte der Prophet Muhammad ﷺ auf die Trauer des kleinen Jungen über den Verlust seines Haustiers?","options":[{"text":"Er setzte sich zu ihm und tröstete ihn mit einfühlsamen, heiteren Reimen auf Augenhöhe.","correct":true},{"text":"Er kaufte dem Jungen auf dem Markt sogleich ein neues Tier, um seinen Schmerz zu lindern.","correct":false},{"text":"Er ermahnte ihn sanft zur Geduld (Ṣabr) und erklärte ihm den natürlichen Kreislauf des Lebens.","correct":false}]},{"title":"Die Trauben im Garten von Ta’if","text":"Nach schweren Enttäuschungen in Mekka reiste der Prophet Muhammad ﷺ in die Stadt Ta’if, um die dortigen Stämme zum Islam einzuladen. Doch die Anführer wiesen ihn hochmütig ab und trieben die Stadtbevölkerung dazu an, ihn mit Steinen zu bewerfen, sodass er blutend fliehen musste. Erschöpft suchte er ﷺ Zuflucht in einem abgelegenen Dattel- und Traubengarten, der den mekkanischen Adligen ʿUtbah und Šaybah gehörte. Als die beiden seinen Zustand sahen, regte sich Mitgefühl. Sie schickten ihren christlichen Diener ʿAddās mit einer Schale frischer Weintrauben zu ihm. Als der Gesandte Allahs ﷺ seine Hand ausstreckte, sprach er vor dem Essen vernehmlich: „Bismillāh“. Der Diener blickte ihn überrascht an und bemerkte, dass die Einheimischen diesen Ausdruck niemals verwendeten. Dies eröffnete ein Gespräch, in dessen Verlauf der Prophet ﷺ Ninive und den rechtschaffenen Propheten Yūnus (Friede sei mit ihm) erwähnte, was den Diener tief ergriff.","question":"Was brachte den Diener ʿAddās im Garten dazu, überrascht ein Gespräch mit dem Propheten ﷺ zu beginnen?","options":[{"text":"Er bemerkte das friedvolle Leuchten auf dem Gesicht des Propheten ﷺ trotz dessen schwerer Verletzungen.","correct":false},{"text":"Der Prophet ﷺ sprach vor dem Verzehr der Trauben die Worte „Bismillāh“ aus.","correct":true},{"text":"Der Prophet ﷺ erkannte sofort die Herkunft des Dieners und sprach ihn gezielt auf dessen christlichen Glauben an.","correct":false}]}];
window.CONTENT_FRAGMENTS={"40:1":[{"end":1,"de":"Ḥā-Mīm.","emoji":"🔤"}],"40:2":[{"end":6,"de":"Die Offenbarung des Buches ist von Allah, dem Allmächtigen, dem Allwissenden,","emoji":"📖"}],"40:3":[{"end":8,"de":"Dem Vergebenden der Sünde und dem Annehmenden der Reue, dem Strengen im Bestrafen, dem Besitzer der Fülle.","emoji":"🤲"},{"end":12,"de":"Es gibt keinen Gott außer Ihm.","emoji":"☝️"},{"end":14,"de":"Zu Ihm ist der Ausgang.","emoji":"↩️"}],"40:4":[{"end":8,"de":"Über die Zeichen Allahs streiten nur diejenigen, die ungläubig sind.","emoji":"🗣️"},{"end":13,"de":"So lasse dich ihr Umherziehen im Land nicht täuschen!","emoji":"🌍"}],"40:5":[{"end":7,"de":"Vor ihnen leugneten bereits das Volk Nūḥs und die Gruppierungen nach ihnen,","emoji":"📜"},{"end":12,"de":"und jede Gemeinschaft hatte vor, sich ihres Gesandten zu bemächtigen.","emoji":"⚔️"},{"end":18,"de":"Und sie stritten mit dem Falschen, um damit die Wahrheit zu widerlegen. Da ergriff Ich sie.","emoji":"💥"},{"end":21,"de":"Wie war da Meine Bestrafung!","emoji":"⚡"}],"40:6":[{"end":10,"de":"Und so hat sich das Wort deines Herrn gegen diejenigen bewahrheitet, die ungläubig sind: dass sie die Gefährten des Feuers sein werden.","emoji":"🔥"}],"40:7":[{"end":13,"de":"Diejenigen, die den Thron tragen, und diejenigen um ihn herum preisen das Lob ihres Herrn, glauben an Ihn und bitten um Vergebung für diejenigen, die glauben:","emoji":"👑"},{"end":24,"de":"Unser Herr, Du umfasst alles an Barmherzigkeit und Wissen; vergib denjenigen, die bereuen und Deinem Weg folgen,","emoji":"🤲"},{"end":27,"de":"und bewahre sie vor der Strafe des Höllenbrandes!","emoji":"🛡️"}],"40:8":[{"end":12,"de":"Unser Herr, lasse sie eingehen in die Gärten von ʿAdn, die Du ihnen versprochen hast, (sie) und wer rechtschaffen ist von ihren Vätern, ihren Gattinnen und ihren Nachkommen.","emoji":"🌳"},{"end":16,"de":"Du bist ja der Allmächtige und Allweise.","emoji":"👑"}],"40:9":[{"end":2,"de":"Und bewahre sie vor den bösen Taten.","emoji":"🛡️"},{"end":8,"de":"Und wen Du an jenem Tag vor den bösen Taten bewahrst, dessen hast Du dich ja erbarmt;","emoji":"🤍"},{"end":12,"de":"und das ist der großartige Erfolg.","emoji":"🏆"}],"40:10":[{"end":15,"de":"Zu denen, die ungläubig sind, wird gewiss ausgerufen werden: Gewiss, Allahs Abscheu ist größer als eure Abscheu vor euch selbst, da ihr zum Glauben aufgerufen wurdet und ungläubig geblieben seid.","emoji":"📢"}],"40:11":[{"end":13,"de":"Sie werden sagen: Unser Herr, Du hast uns zweimal sterben lassen und zweimal lebendig gemacht. Nun bekennen wir unsere Sünden. Gibt es denn einen Weg zum Hinausgelangen?","emoji":"🚪"}],"40:12":[{"end":7,"de":"Dies (geschieht euch), weil ihr, als Allah allein angerufen wurde, ungläubig wart;","emoji":"❌"},{"end":11,"de":"aber wenn Ihm (andere) beigesellt wurden, glaubtet ihr.","emoji":"👥"},{"end":15,"de":"Das Urteil gehört Allah, dem Erhabenen, dem Großen.","emoji":"⚖️"}],"40:13":[{"end":9,"de":"Er ist es, Der euch Seine Zeichen zeigt und euch vom Himmel Versorgung hinabsendet.","emoji":"🌧️"},{"end":14,"de":"Aber bedenken tut es nur, wer sich (Allah reuevoll) zuwendet.","emoji":"↩️"}],"40:14":[{"end":8,"de":"So ruft Allah an, indem ihr Ihm gegenüber aufrichtig in der Religion seid, auch wenn es den Ungläubigen zuwider ist.","emoji":"🤲"}],"40:15":[{"end":16,"de":"(Er ist es,) Der hohe Rangstufen hat, der Herr des Thrones. Er gibt den Geist von Seinem Befehl, wem von Seinen Dienern Er will, damit er vor dem Tag der Begegnung warne,","emoji":"📜"}],"40:16":[{"end":3,"de":"dem Tag, an dem sie vortreten,","emoji":"👥"},{"end":9,"de":"und nichts von ihnen vor Allah verborgen bleibt.","emoji":"👁️"},{"end":12,"de":"Wem gehört die Herrschaft heute?","emoji":"❓"},{"end":15,"de":"Allah, dem Einen, dem Allbezwinger.","emoji":"☝️"}],"40:17":[{"end":6,"de":"Heute wird jeder Seele das vergolten, was sie erworben hat.","emoji":"⚖️"},{"end":9,"de":"Kein Unrecht gibt es heute.","emoji":"🚫"},{"end":13,"de":"Gewiss, Allah ist schnell im Abrechnen.","emoji":"⚡"}],"40:18":[{"end":8,"de":"Und warne sie vor dem Tag der herannahenden (Entscheidung), da die Herzen in der Kehle sitzen, den Gram unterdrückend.","emoji":"⚠️"},{"end":15,"de":"Die Ungerechten haben weder einen warmen Freund noch einen Fürsprecher, dem Gehör geschenkt würde.","emoji":"👤"}],"40:19":[{"end":6,"de":"Er weiß, was die Blicke an Verräterischem tun und was die Brüste verbergen.","emoji":"👁️"}],"40:20":[{"end":3,"de":"Und Allah entscheidet nach der Wahrheit.","emoji":"⚖️"},{"end":10,"de":"Diejenigen aber, die sie anstatt Seiner anrufen, entscheiden nichts.","emoji":"🪨"},{"end":15,"de":"Gewiss, Allah ist der Allhörende, der Allsehende.","emoji":"👂"}],"40:21":[{"end":12,"de":"Sind sie denn nicht auf der Erde umhergereist, so dass sie schauen (konnten), wie das Ende derjenigen war, die vor ihnen waren?","emoji":"🌍"},{"end":30,"de":"Sie waren ja stärker als sie an Kraft und hinterließen mehr Spuren auf der Erde. Da ergriff sie Allah für ihre Sünden; und sie hatten vor Allah keinen Beschützer.","emoji":"🏛️"}],"40:22":[{"end":9,"de":"Dies (geschah deshalb), weil ihre Gesandten mit den klaren Beweisen zu ihnen kamen, sie aber ungläubig blieben; da ergriff sie Allah.","emoji":"📜"},{"end":13,"de":"Gewiss, Er ist Stark und streng im Bestrafen.","emoji":"💥"}],"40:23":[{"end":6,"de":"Und Wir sandten ja bereits Mūsā mit Unseren Zeichen und einer deutlichen Ermächtigung","emoji":"🌊"}],"40:24":[{"end":7,"de":"zu Firʿawn, Hāmān und Qārūn. Da sagten sie: Ein Zauberer, ein verlogener.","emoji":"👑"}],"40:25":[{"end":13,"de":"Als er ihnen nun die Wahrheit von Uns brachte, sagten sie: Tötet die Söhne derjenigen, die mit ihm glauben, und lasst ihre Frauen am Leben.","emoji":"⚔️"},{"end":19,"de":"Aber die List der Ungläubigen geht gewiss verloren.","emoji":"🕸️"}],"40:26":[{"end":7,"de":"Und Pharao sagte: Lasst mich Mūsā töten! Er soll seinen Herrn anrufen!","emoji":"🗡️"},{"end":18,"de":"Ich fürchte nämlich, dass er eure Religion ändert oder dass er auf der Erde Unheil stiftet.","emoji":"⚠️"}],"40:27":[{"end":13,"de":"Und Mūsā sagte: Ich nehme Zuflucht zu meinem Herrn und eurem Herrn vor jedem Hochmütigen, der nicht an den Tag der Abrechnung glaubt.","emoji":"🛡️"}],"40:28":[{"end":19,"de":"Ein gläubiger Mann von den Leuten Pharaos, der seinen Glauben verheimlichte, sagte: Wollt ihr denn einen Mann töten, weil er sagt: Mein Herr ist Allah, wo er doch mit den klaren Beweisen von eurem Herrn zu euch gekommen ist?","emoji":"🗣️"},{"end":24,"de":"Wenn er ein Lügner ist, so geht seine Lüge zu seinen Lasten;","emoji":"🤥"},{"end":31,"de":"wenn er aber die Wahrheit sagt, wird euch etwas von dem treffen, was er euch androht.","emoji":"⚡"},{"end":39,"de":"Gewiss, Allah leitet niemanden recht, wer maßlos und verlogen ist.","emoji":"🚫"}],"40:29":[{"end":14,"de":"O mein Volk, euer ist heute die Herrschaft, da ihr auf der Erde die Oberhand habt. Wer aber wird uns vor Allahs Strenge helfen, wenn sie über uns kommt?","emoji":"👑"},{"end":26,"de":"Pharao sagte: Ich weise euch nur auf das hin, was ich sehe, und ich leite euch nur auf den Weg des rechten Handelns.","emoji":"🗣️"}],"40:30":[{"end":10,"de":"Und derjenige, der glaubte, sagte: O mein Volk, ich fürchte um euch das Gleiche wie den Tag der Gruppierungen,","emoji":"⚠️"}],"40:31":[{"end":9,"de":"wie den gewohnten Zustand des Volkes Nūḥs, der ʿĀd, der Ṯamūd und derjenigen nach ihnen.","emoji":"📜"},{"end":14,"de":"Und Allah will kein Unrecht für die Diener.","emoji":"⚖️"}],"40:32":[{"end":6,"de":"O mein Volk, gewiss, ich fürchte um euch den Tag des gegenseitigen Zurufens,","emoji":"📢"}],"40:33":[{"end":9,"de":"den Tag, an dem ihr den Rücken kehrt und flieht, ohne dass ihr vor Allah einen Schützer hättet.","emoji":"🏃"},{"end":16,"de":"Und wen Allah in die Irre gehen lässt, der hat niemanden, der ihn rechtleitet.","emoji":"🌫️"}],"40:34":[{"end":13,"de":"Und Yūsuf war ja bereits zuvor mit den klaren Beweisen zu euch gekommen. Aber ihr habt nicht aufgehört, über das im Zweifel zu sein, was er euch brachte,","emoji":"📜"},{"end":23,"de":"bis er dann starb und ihr sagtet: Allah wird nach ihm gewiss keinen Gesandten mehr erstehen lassen.","emoji":"⌛"},{"end":30,"de":"So lässt Allah irregehen, wer maßlos und zweiflerisch ist.","emoji":"🌫️"}],"40:35":[{"end":8,"de":"Diejenigen, die über die Zeichen Allahs streiten, ohne dass eine Ermächtigung zu ihnen gekommen wäre,","emoji":"🗣️"},{"end":15,"de":"haben großen Abscheu bei Allah und bei denjenigen, die glauben, erregt.","emoji":"⚠️"},{"end":23,"de":"So versiegelt Allah das Herz eines jeden Hochmütigen, Gewalttätigen.","emoji":"🔒"}],"40:36":[{"end":9,"de":"Und Pharao sagte: O Hāmān, baue mir einen Hochsitz, vielleicht erreiche ich die Zugänge,","emoji":"🏗️"}],"40:37":[{"end":9,"de":"die Zugänge zu den Himmeln, dass ich zum Gott Mūsās emporsteige; gewiss, ich halte ihn für einen Lügner.","emoji":"🌌"},{"end":17,"de":"Und so wurde Pharao sein böses Tun ausgeschmückt, und er wurde vom (rechten) Weg abgehalten.","emoji":"🥀"},{"end":23,"de":"Aber die List Pharaos ging nur zugrunde.","emoji":"🕸️"}],"40:38":[{"end":8,"de":"Und derjenige, der glaubte, sagte: O mein Volk, folgt mir, so leite ich euch auf den Weg des rechten Handelns.","emoji":"🧭"}],"40:39":[{"end":11,"de":"O mein Volk, dieses irdische Leben ist nur Nießbrauch; das Jenseits aber ist die Wohnstätte des Bleibens.","emoji":"⏳"}],"40:40":[{"end":7,"de":"Wer eine böse Tat begeht, dem wird nur mit Gleichwertigem vergolten;","emoji":"⚖️"},{"end":23,"de":"wer aber rechtschaffen handelt, ob Mann oder Frau, und dabei gläubig ist, jene werden in den Paradiesgarten eingehen, wo sie versorgt werden ohne Abrechnung.","emoji":"🌸"}],"40:41":[{"end":9,"de":"O mein Volk, wie kommt es, dass ich euch zur Rettung rufe, während ihr mich zum Feuer ruft?","emoji":"📢"}],"40:42":[{"end":10,"de":"Ihr ruft mich dazu auf, Allah zu verleugnen und Ihm das beizugesellen, wovon ich kein Wissen habe,","emoji":"❌"},{"end":15,"de":"während ich euch zum Allmächtigen, zum Allvergebenden rufe.","emoji":"🤲"}],"40:43":[{"end":13,"de":"Zweifellos gebührt dem, wozu ihr mich ruft, keine Anrufung, weder im Diesseits noch im Jenseits,","emoji":"🪨"},{"end":17,"de":"und unsere Rückkehr ist gewiss zu Allah,","emoji":"↩️"},{"end":22,"de":"und die Maßlosen sind gewiss die Gefährten des Feuers.","emoji":"🔥"}],"40:44":[{"end":4,"de":"So werdet ihr an das denken, was ich euch sage.","emoji":"⏳"},{"end":8,"de":"Und ich überlasse meine Angelegenheit Allah.","emoji":"🤲"},{"end":12,"de":"Gewiss, Allah sieht die Diener wohl.","emoji":"👁️"}],"40:45":[{"end":5,"de":"Da bewahrte ihn Allah vor den Bosheiten ihrer Ränke,","emoji":"🛡️"},{"end":10,"de":"und die Sippe Pharaos umringte die schlimme Strafe:","emoji":"🌊"}],"40:46":[{"end":5,"de":"das Feuer, dem sie morgens und abends vorgeführt werden.","emoji":"🔥"},{"end":13,"de":"Und am Tag, da die Stunde heraufzieht: Lasst die Sippe Pharaos die strengste Strafe erleiden!","emoji":"⚖️"}],"40:47":[{"end":12,"de":"Und wenn sie im Feuer miteinander streiten, da sagen die Schwachen zu denjenigen, die sich hochmütig verhielten: Gewiss, wir waren eure Gefolgsleute;","emoji":"🗣️"},{"end":19,"de":"könnt ihr uns nun einen Teil des Feuers abnehmen?","emoji":"❓"}],"40:48":[{"end":6,"de":"Diejenigen, die sich hochmütig verhielten, sagen: Gewiss, wir befinden uns alle darin.","emoji":"⛓️"},{"end":12,"de":"Gewiss, Allah hat bereits zwischen den Dienern gerichtet.","emoji":"⚖️"}],"40:49":[{"end":13,"de":"Und diejenigen, die im Feuer sind, sagen zu den Wärtern der Hölle: Ruft euren Herrn an, dass Er uns einen Tag von der Strafe erlasse!","emoji":"🔥"}],"40:50":[{"end":6,"de":"Sie sagen: Kamen nicht doch eure Gesandten mit den klaren Beweisen zu euch?","emoji":"❓"},{"end":8,"de":"Sie sagen: Jawohl!","emoji":"🗣️"},{"end":10,"de":"Sie sagen: So ruft an!","emoji":"📢"},{"end":16,"de":"Aber das Rufen der Ungläubigen geht gewiss verloren.","emoji":"🕸️"}],"40:51":[{"end":11,"de":"Gewiss, Wir helfen Unseren Gesandten und denjenigen, die glauben, im irdischen Leben und am Tag, da die Zeugen auftreten,","emoji":"🛡️"}],"40:52":[{"end":5,"de":"dem Tag, an dem den Ungerechten ihre Entschuldigung nicht nützt;","emoji":"🚫"},{"end":10,"de":"und ihnen wird der Fluch zuteil, und ihnen wird die böse Wohnstätte zuteil.","emoji":"🔥"}],"40:53":[{"end":8,"de":"Und Wir gaben bereits Mūsā die Rechtleitung und ließen die Kinder Isrāʾīls die Schrift erben,","emoji":"📜"}],"40:54":[{"end":4,"de":"als Rechtleitung und Ermahnung für diejenigen, die Verstand besitzen.","emoji":"💡"}],"40:55":[{"end":12,"de":"Sei nun standhaft! Gewiss, Allahs Versprechen ist wahr. Und bitte um Vergebung für deine Sünde und preise das Lob deines Herrn am Abend und am frühen Morgen.","emoji":"🤲"}],"40:56":[{"end":17,"de":"Gewiss, diejenigen, die über Allahs Zeichen streiten, ohne dass eine Ermächtigung zu ihnen gekommen wäre, haben in ihren Brüsten nur Hochmut, den sie nicht verwirklichen können.","emoji":"👤"},{"end":19,"de":"So nimm Zuflucht bei Allah;","emoji":"🛡️"},{"end":23,"de":"gewiss, Er ist der Allhörende, der Allsehende.","emoji":"👂"}],"40:57":[{"end":12,"de":"Wahrlich, die Erschaffung der Himmel und der Erde ist größer als die Erschaffung der Menschen. Aber die meisten Menschen wissen nicht.","emoji":"🌌"}],"40:58":[{"end":10,"de":"Nicht gleich sind der Blinde und der Sehende und diejenigen, die glauben und rechtschaffene Werke tun, und der Missetäter.","emoji":"⚖️"},{"end":13,"de":"Wie wenig ihr bedenkt!","emoji":"💭"}],"40:59":[{"end":11,"de":"Gewiss, die Stunde kommt bestimmt, an ihr gibt es keinen Zweifel. Aber die meisten Menschen glauben nicht.","emoji":"⏳"}],"40:60":[{"end":5,"de":"Euer Herr sagt: Ruft Mich an, so erhöre Ich euch.","emoji":"🤲"},{"end":13,"de":"Gewiss, diejenigen, die sich aus Hochmut weigern, Mir zu dienen, werden demütig in die Hölle eingehen.","emoji":"🔥"}],"40:61":[{"end":10,"de":"Allah ist es, Der euch die Nacht gemacht hat, damit ihr in ihr ruht, und den Tag hell.","emoji":"🌙"},{"end":20,"de":"Gewiss, Allah ist voll Huld gegen die Menschen. Aber die meisten Menschen sind nicht dankbar.","emoji":"🌾"}],"40:62":[{"end":10,"de":"Das ist doch Allah, euer Herr, der Schöpfer von allem. Es gibt keinen Gott außer Ihm.","emoji":"☝️"},{"end":12,"de":"Wie lasst ihr euch also abwendig machen?","emoji":"❓"}],"40:63":[{"end":7,"de":"So lassen sich diejenigen abwendig machen, die Allahs Zeichen zu leugnen pflegten.","emoji":"🚫"}],"40:64":[{"end":14,"de":"Allah ist es, Der euch die Erde zu einem festen Grund und den Himmel zu einem Bau gemacht, euch gestaltet und eure Gestalten schön gemacht und euch von den guten Dingen versorgt hat.","emoji":"🌍"},{"end":17,"de":"Das ist doch Allah, euer Herr.","emoji":"👑"},{"end":21,"de":"Segensreich ist Allah, der Herr der Weltenbewohner!","emoji":"✨"}],"40:65":[{"end":10,"de":"Er ist der Lebendige. Es gibt keinen Gott außer Ihm. So ruft Ihn an, indem ihr Ihm gegenüber aufrichtig in der Religion seid.","emoji":"🤲"},{"end":14,"de":"Alles Lob gebührt Allah, dem Herrn der Weltenbewohner.","emoji":"🤍"}],"40:66":[{"end":20,"de":"Sag: Mir ist es untersagt worden, denjenigen zu dienen, die ihr anstatt Allahs anruft, nachdem zu mir die klaren Beweise von meinem Herrn gekommen sind, und mir ist befohlen worden, mich dem Herrn der Weltenbewohner zu unterwerfen.","emoji":"🛑"}],"40:67":[{"end":20,"de":"Er ist es, Der euch aus Erde erschaffen hat, hierauf aus einem Samentropfen, hierauf aus einem Anhängsel. Hierauf lässt Er euch als kleines Kind hervorkommen. Hierauf (lässt Er euch heranwachsen), damit ihr eure Vollkraft erreicht und damit ihr dann Greise werdet","emoji":"🌱"},{"end":25,"de":"– manche von euch werden schon vorher abberufen –","emoji":"⚰️"},{"end":30,"de":"und damit ihr eine festgesetzte Frist erreicht, und auf dass ihr begreifen mögt.","emoji":"⏳"}],"40:68":[{"end":4,"de":"Er ist es, Der lebendig macht und sterben lässt.","emoji":"🔄"},{"end":12,"de":"Wenn Er eine Sache beschließt, so sagt Er zu ihr nur: Sei!, und so ist sie.","emoji":"🗣️"}],"40:69":[{"end":10,"de":"Siehst du nicht diejenigen, die über die Zeichen Allahs streiten, wie sie sich abwenden lassen?","emoji":"❓"}],"40:70":[{"end":7,"de":"Diejenigen, die das Buch und das leugnen, womit Wir Unsere Gesandten gesandt haben;","emoji":"📖"},{"end":9,"de":"sie werden es aber noch erfahren,","emoji":"⚠️"}],"40:71":[{"end":6,"de":"wenn die Fesseln und die Ketten um ihre Hälse gelegt sind und sie gezerrt werden","emoji":"⛓️"}],"40:72":[{"end":6,"de":"ins siedende Wasser und hierauf im Feuer gepeinigt werden.","emoji":"🔥"}],"40:73":[{"end":7,"de":"Hierauf wird zu ihnen gesagt werden: Wo ist das, was ihr beizugesellen pflegtet","emoji":"❓"}],"40:74":[{"end":3,"de":"anstatt Allahs?","emoji":"🪨"},{"end":12,"de":"Sie werden sagen: Sie sind uns entschwunden; nein, vielmehr haben wir vordem gar nichts angerufen.","emoji":"💨"},{"end":17,"de":"So lässt Allah die Ungläubigen irregehen.","emoji":"🌫️"}],"40:75":[{"end":11,"de":"Dies dafür, dass ihr auf der Erde ohne Recht frohlockt und ausgelassen zu sein pflegtet.","emoji":"🎉"}],"40:76":[{"end":5,"de":"Betretet die Tore der Hölle, ewig darin zu bleiben.","emoji":"🚪"},{"end":8,"de":"Wie schlimm ist die Bleibe der Hochmütigen!","emoji":"🥀"}],"40:77":[{"end":5,"de":"Sei nun standhaft! Gewiss, Allahs Versprechen ist wahr.","emoji":"🤲"},{"end":14,"de":"Ob Wir dir nun einen Teil von dem zeigen, was Wir ihnen androhen, oder dich vorher abberufen – zu Uns werden sie zurückgebracht.","emoji":"↩️"}],"40:78":[{"end":14,"de":"Und Wir sandten ja bereits Gesandte vor dir; unter ihnen sind manche, von denen Wir dir berichtet haben, und unter ihnen sind manche, von denen Wir dir nicht berichtet haben.","emoji":"📜"},{"end":23,"de":"Kein Gesandter kann ein Zeichen bringen außer mit Allahs Erlaubnis.","emoji":"☝️"},{"end":32,"de":"Wenn dann Allahs Befehl kommt, wird nach der Wahrheit entschieden, und verloren haben da diejenigen, die (alles) für nichtig erklären.","emoji":"⚖️"}],"40:79":[{"end":9,"de":"Allah ist es, Der euch das Vieh gemacht hat, damit ihr teils auf ihm reitet; und teils ernährt ihr euch von ihm.","emoji":"🐪"}],"40:80":[{"end":12,"de":"Und ihr habt an ihm (allerlei) Nutzen, und damit ihr darauf ein Anliegen erreicht, das in euren Brüsten ist; und auf ihm und auf den Schiffen werdet ihr getragen.","emoji":"🚢"}],"40:81":[{"end":6,"de":"Und Er zeigt euch Seine Zeichen. Welche der Zeichen Allahs wollt ihr denn leugnen?","emoji":"🌌"}],"40:82":[{"end":11,"de":"Sind sie denn nicht auf der Erde umhergereist, so dass sie schauen (konnten), wie das Ende derjenigen war, die vor ihnen waren?","emoji":"🌍"},{"end":25,"de":"Sie waren zahlreicher als sie, und sie hatten mehr Kraft und hinterließen mehr Spuren auf der Erde. Doch nützte ihnen nicht, was sie zu erwerben pflegten.","emoji":"🏛️"}],"40:83":[{"end":15,"de":"Als ihre Gesandten mit den klaren Beweisen zu ihnen kamen, frohlockten sie über das Wissen, das sie hatten, aber es umschloss sie das, worüber sie sich lustig zu machen pflegten.","emoji":"📚"}],"40:84":[{"end":12,"de":"Als sie dann Unsere Strenge sahen, sagten sie: Wir glauben an Allah allein und verleugnen das, was wir Ihm beizugesellen pflegten.","emoji":"⚡"}],"40:85":[{"end":7,"de":"Aber ihr Glaube nützte ihnen nichts mehr, als sie Unsere Strenge sahen.","emoji":"⌛"},{"end":14,"de":"(So ist) Allahs Gesetzmäßigkeit, die schon zuvor an Seinen Dienern vollzogen worden ist;","emoji":"📜"},{"end":17,"de":"und verloren sind da die Ungläubigen.","emoji":"🥀"}]};
window.CONTENT_MUNASABA={"start":{"40":{"t":"Die Sure Ġāfir will nach al-Biqāʿī den unberechtigten Streit gegen die Offenbarung entlarven und den Gesandten ﷺ sowie die Gläubigen trösten.","q":"Womit eröffnet die Sure, um die Aufmerksamkeit auf das Buch zu lenken?"}},"frag":{"40:1":[{"t":"Mit zwei einzelnen Buchstaben, aus denen auch die arabische Sprache des Qurʾān besteht. So lenkt die Sure den Blick auf das Wunder dieser Sprache.","q":"Wenn das Buch aus solchen Buchstaben besteht: Woher kommt es?"}],"40:2":[{"t":"Es ist keine Menschendichtung, sondern herabgesandt von Allah, dem Allmächtigen (niemand kann es aufhalten oder verfälschen), dem Allwissenden (es ist voll von Wissen).","q":"Wie begegnet dieser mächtige Absender den Menschen, die das Buch hören?"}],"40:3":[{"t":"Wer umkehrt, dem vergibt Er und nimmt seine Reue an; wer hochmütig bleibt, den straft Er streng. Als Besitzer der Fülle (Ḏī aṭ-Ṭawl) lässt Er Seine Gunst allem vorausgehen.","q":"Gibt es neben diesem Vergebenden und Strafenden noch einen anderen, an den man sich wenden kann?"},{"t":"Nein, es gibt keinen Gott außer Ihm. Nach al-Biqāʿī ist damit jede Fluchtmöglichkeit zu einem anderen ausgeschlossen.","q":"Und wohin führt am Ende der Weg aller Menschen?"},{"t":"Zu Ihm kehren alle ausnahmslos zurück. Damit steht fest: Das Buch kommt vom Allmächtigen, Allwissenden, Barmherzigen und Gerechten, dem niemand entkommt.","q":"Wenn das alles so klar ist: Warum streiten manche trotzdem über dieses Buch?"}],"40:4":[{"t":"Nicht aus Mangel an Beweisen: Über die Zeichen Allahs streiten nur die Ungläubigen, und zwar aus Unglauben und Hochmut.","q":"Wie soll der Prophet ﷺ ihre Macht und ihren Handelserfolg im Land ansehen?"},{"t":"Ihr Erfolg und ihr Umherreisen in den Ländern soll dich (den Propheten ﷺ) nicht täuschen. Nach al-Biqāʿī ist dieses Wohlleben nur ein zeitweiliger Aufschub.","q":"Sind die heutigen Leugner die ersten, die die Botschaft zurückweisen?"}],"40:5":[{"t":"Nein, schon vor ihnen leugneten das Volk Nūḥs und die Gruppen nach ihnen. Das Leugnen ist keine neue Erfindung der Quraisch, sondern die Methode früherer Völker.","q":"Blieb es bei den früheren Völkern beim bloßen Leugnen ihrer Gesandten?"},{"t":"Nein, jede Gemeinschaft plante gegen ihren Gesandten und wollte sich seiner bemächtigen. Aus dem Leugnen wurde ein Vorgehen gegen seine Person.","q":"Und womit versuchten sie, die Botschaft ihrer Gesandten zu Fall zu bringen?"},{"t":"Sie stritten mit dem Falschen, um die Wahrheit zu widerlegen, genau wie die Streiter aus Vers 4. Doch Allah ﷻ ergriff sie und vernichtete sie.","q":"Welcher Name Allahs aus Vers 3 wird durch dieses Ergreifen bestätigt?"},{"t":"Die rhetorische Frage „Wie war da Meine Bestrafung!“ bestätigt den Namen Šadīd al-ʿIqāb, „streng im Strafen“, aus Vers 3.","q":"Gilt das nur für die Völker von damals?"}],"40:6":[{"t":"Nein, genauso steht das Wort deines Herrn auch über die heutigen Leugner fest: Sie sind die Gefährten des Feuers. Ihre Rastlosigkeit im Land (Vers 4) endet im Feuer.","q":"Und die Gläubigen, die von diesen Streitenden bedrängt werden: Stehen sie allein da?"}],"40:7":[{"t":"Nein: Während auf der Erde gestritten wird, preisen die gewaltigsten Geschöpfe, die Träger des Throns und die Engel um ihn, Allah und bitten um Vergebung für die Gläubigen.","q":"Auf welche Eigenschaften Allahs stützen die Engel ihre Bitte um Vergebung?"},{"t":"Auf Seine Barmherzigkeit und Sein Wissen, die alles umfassen; so bitten sie um Vergebung für die Reuigen. Das greift al-ʿAlīm, Ġāfir aḏ-Ḏanb und Qābil at-Tawb aus Vers 2–3 auf.","q":"Wovor sollen die reuigen Gläubigen nach der Bitte der Engel bewahrt werden?"},{"t":"Vor der Strafe des Höllenbrandes. Was Allah am Anfang über Seine Barmherzigkeit offenbarte, setzen die Engel hier in Fürbitte für die Gläubigen um.","q":"Reicht es den Gläubigen, nur vor der Hölle bewahrt zu werden?"}],"40:8":[{"t":"Nein, die Engel bitten auch um das Gute: den Eintritt in die Gärten von ʿAdn mit den rechtschaffenen Vätern, Ehepartnern und Nachkommen. Verwandtschaft ohne Glauben nützt nichts.","q":"Mit welchen Namen Allahs begründen die Engel diese Bitte?"},{"t":"Sie begründen ihre Bitte mit Allahs Namen: Er ist der Allmächtige und der Allweise. Wie schon in Vers 7 stützen die Engel ihr Gebet auf Seine Eigenschaften.","q":"Was erbitten die Engel außerdem, damit die Gläubigen sicher ins Paradies gelangen?"}],"40:9":[{"t":"Die Engel bitten auch um Schutz vor den schlechten Taten und deren Folgen (wa-qihimu-s-sayyiʾāt), damit die Gläubigen sicher ins Paradies gelangen.","q":"Was bedeutet es für jemanden, wenn Allah ihn an jenem Tag davor bewahrt?"},{"t":"Wen Allah an jenem Tag vor den bösen Taten und ihren Folgen bewahrt, dessen hat Er sich erbarmt. Diese Bewahrung ist selbst ein Zeichen Seiner Barmherzigkeit.","q":"Wie ist diese Bewahrung im Vergleich zum Gewinn der Ungläubigen aus Vers 4 einzuordnen?"},{"t":"Sie ist der gewaltige Gewinn. Nach al-Biqāʿī ist er der wahre Gegensatz zum scheinbaren Gewinn der Ungläubigen, deren irdischen Reichtum Vers 4 erwähnte.","q":"Und wie ergeht es an jenem Tag den Ungläubigen?"}],"40:10":[{"t":"Als sie ihr Verderben sehen, verabscheuen sie sich selbst. Doch ihnen wird zugerufen: Allahs Abscheu war noch größer, als ihr im Diesseits zum Glauben gerufen wurdet und ablehntet.","q":"Was sagen die Ungläubigen daraufhin zu ihrem Herrn?"}],"40:11":[{"t":"Zu spät erkennen sie an, dass Allah sie zweimal sterben und zweimal leben ließ. Sie gestehen ihre Sünden und fragen nach einem Weg hinaus, doch diese Hoffnung ist reine Illusion.","q":"Warum gibt es für sie keinen Ausweg?"}],"40:12":[{"t":"Weil sie ungläubig waren, wenn Allah allein angerufen wurde. Sie nahmen Anstoß an Seiner reinen Einheit (Tawḥīd).","q":"Und wann dagegen waren sie zum Glauben bereit?"},{"t":"Wenn Ihm andere beigesellt wurden, glaubten sie. Al-Biqāʿī sieht darin die innere Verdorbenheit ihrer Herzen: Sie freuten sich am Götzendienst (Širk).","q":"Wem gehört deshalb das Urteil über sie?"},{"t":"Das gerechte Urteil gehört allein Allah, der über allem erhaben ist: dem Erhabenen, dem Großen (al-ʿAlī, al-Kabīr).","q":"Hätten sie Allahs Einzigkeit schon im Diesseits erkennen können?"}],"40:13":[{"t":"Ja, Er zeigt euch ständig Seine Zeichen und sendet euch Versorgung vom Himmel: Regen und damit geistige wie materielle Nahrung. Die Beweise Seiner Einzigkeit umgeben euch.","q":"Ziehen denn alle Menschen aus diesen Zeichen eine Lehre?"},{"t":"Nein, nur wer reumütig zu Allah umkehrt, lässt sich ermahnen. Wer hochmütig streitet, sieht diese Zeichen nicht.","q":"Was folgt daraus, dass Er allein Zeichen zeigt und Versorgung herabsendet?"}],"40:14":[{"t":"So ruft Allah allein an, aufrichtig in der Religion, auch wenn es den Ungläubigen zuwider ist. Das „Fa“ in „fa-dʿū“ markiert diesen Aufruf als Folge aus Vers 13.","q":"Warum gebührt der aufrichtige Dienst nur Ihm und keinem anderen?"}],"40:15":[{"t":"Weil Er über alle Ränge erhaben ist und der Herr des Throns. Er sendet die Offenbarung (ar-Rūḥ, die tote Herzen lebendig macht) auf Seine Gesandten, um vor dem Tag der Begegnung zu warnen.","q":"Was geschieht mit den Menschen an diesem Tag der Begegnung?"}],"40:16":[{"t":"An diesem Tag treten alle offen hervor. Es gibt keine Schleier mehr, keine Machtansprüche von Herrschern und keinen Raum für Streit oder Götzen.","q":"Kann dann noch etwas von ihnen vor Allah verborgen sein?"},{"t":"Nein, nichts von ihnen bleibt Allah verborgen. Da es keine Schleier mehr gibt, liegt alles an ihnen offen vor Ihm.","q":"Welche Frage stellt Allah an jenem Tag der ganzen Schöpfung?"},{"t":"Er fragt: „Wem gehört heute die Herrschaft?“ Nach al-Biqāʿī schweigt die gesamte Schöpfung in Ehrfurcht vor der Wucht dieser Frage.","q":"Welche Antwort folgt auf diese Frage, während alles schweigt?"},{"t":"Die Antwort lautet: Allah, dem Einen, dem Allbezwinger. Damit ist das trügerische Umherziehen und Prahlen der Ungläubigen aus Vers 4 endgültig vorbei.","q":"Was folgt aus dieser alleinigen Herrschaft an jenem Tag?"}],"40:17":[{"t":"Aus Seiner alleinigen Herrschaft folgt vollkommene Gerechtigkeit: Heute bekommt jede Seele genau das vergolten, was sie selbst erworben hat.","q":"Wird dabei einer Seele mehr angelastet, als sie verdient hat?"},{"t":"Nein, heute gibt es kein Unrecht. Weil Allah von nichts abhängig ist, gibt es für Ihn keinen Grund zu Parteilichkeit oder Unrecht.","q":"Dauert es lange, bis über jede einzelne Seele abgerechnet ist?"},{"t":"Nein, Allah ist schnell im Abrechnen. So ist die Abrechnung vollkommen: gerechter Lohn für jede Seele, kein Unrecht und kein langes Warten.","q":"Wenn diese Abrechnung so gewiss ist: Was soll der Prophet ﷺ tun?"}],"40:18":[{"t":"Er soll sie vor dem Tag al-Āzifa, dem „Nahenden“, warnen. Der Name zeigt: Alles Künftige ist schon nah, und an diesem Tag steigen die Herzen vor Angst bis zur Kehle.","q":"Finden die Ungerechten an diesem Tag jemanden, der ihnen beisteht?"},{"t":"Nein, sie haben weder einen treuen Freund noch einen Fürsprecher, der gehört wird. Ganz anders die Gläubigen, für die nach Vers 7–9 die Thronträger bitten.","q":"Worauf beruht es, dass Allahs Urteil ganz ohne Unrecht sein kann?"}],"40:19":[{"t":"Auf vollkommenem Wissen: Allah kennt selbst den flüchtigsten verräterischen Blick und alles, was die Herzen sorgfältig verbergen.","q":"Wie fällt Allah mit diesem Wissen Sein Urteil?"}],"40:20":[{"t":"Er entscheidet nach der Wahrheit. Hier schließt sich der Kreis zu Vers 12: Das Urteil steht allein Allah zu.","q":"Können auch die, die man neben Allah anruft, über etwas entscheiden?"},{"t":"Nein, sie entscheiden über gar nichts. Die angebeteten Götzen haben weder Wissen noch Schöpfungskraft und können darum nicht richten.","q":"Entgeht Allah etwas von dem, was ihre Anbeter reden und tun?"},{"t":"Nein, Er ist der Allhörende, der ihre Streitreden hört, und der Allsehende, der ihre Taten sieht. Das ist eine erneute Mahnung an die Widersacher.","q":"Die Leugner sehen das Jenseits nicht: Gibt es einen Beweis, den sie schon heute sehen können?"}],"40:21":[{"t":"Ja, die Spuren früherer Völker auf der Erde. Wer das Jenseits leugnet, kann diese sichtbaren Überreste nicht leugnen, darum sollen sie reisen und ihr Ende anschauen.","q":"Wie mächtig waren diese früheren Völker im Vergleich zu ihnen?"},{"t":"Sie waren stärker und hinterließen mehr Spuren, doch Allah ergriff sie für ihre Sünden, und niemand schützte sie. Damit ist der Stolz der Leugner auf ihre Macht (Vers 4) widerlegt.","q":"Worin lag ihre Schuld, für die Allah sie ergriff?"}],"40:22":[{"t":"Darin, dass sie ungläubig blieben, obwohl ihre Gesandten mit klaren Beweisen kamen. Damit wird erneut das Grundübel der Sure hervorgehoben: das Verwerfen der Offenbarung.","q":"Welche Eigenschaften Allahs zeigen sich darin, dass Er diese Völker ergriff?"},{"t":"Er ist stark und streng im Bestrafen. Diese Worte knüpfen wörtlich an Vers 3 an und bestätigen das dort genannte Prinzip an den früheren Völkern.","q":"Gibt es ein konkretes Beispiel für einen Gesandten mit klaren Beweisen?"}],"40:23":[{"t":"Ja, Mūsā (Friede sei auf ihm), gesandt mit Allahs Zeichen und einer deutlichen Vollmacht. Nach der allgemeinen Aussage folgt nun das prägnanteste Beispiel.","q":"Zu wem wurde er gesandt, und wie reagierten sie?"}],"40:24":[{"t":"Zu Firʿawn (politische Macht), Hāmān (Verwaltung und Planung) und Qārūn (Macht des Geldes). Trotz der klaren Vollmacht schmähten sie ihn nur: „Ein Zauberer, ein Lügner!“","q":"Was taten sie, als ihre Schmähungen gegen die Wahrheit nichts ausrichteten?"}],"40:25":[{"t":"Sie griffen zur Gewalt: Die Söhne der Gläubigen sollten getötet und ihre Frauen am Leben gelassen werden, um die Träger des Glaubens auszulöschen.","q":"Wird dieser grausame Plan sein Ziel erreichen?"},{"t":"Nein, die List der Ungläubigen geht verloren. Jede List, die gegen die Wahrheit geschmiedet wird, verläuft sich im Nichts und führt in den Untergang.","q":"Was plant Firʿawn als Nächstes, nachdem diese List gescheitert ist?"}],"40:26":[{"t":"Er will Mūsā nun selbst töten. Sein „Lasst mich“ soll klingen, als hielten ihn seine Ratgeber zurück, dabei lag die Furcht in seinem eigenen Herzen.","q":"Wie rechtfertigt Firʿawn diesen Mordplan vor seinem Volk?"},{"t":"Er stellt Mūsā als Unruhestifter dar, der ihre Religion ändern und Unheil im Land stiften wolle. So verdreht er die Tatsachen, um den Mord zu rechtfertigen.","q":"Wie antwortet Mūsā auf diese Drohung?"}],"40:27":[{"t":"Nicht mit einer Gegendrohung, sondern mit Gottvertrauen: Er nimmt Zuflucht bei seinem und ihrem Herrn vor jedem Hochmütigen, der den Tag der Abrechnung leugnet.","q":"Wie beantwortet Allah Mūsās Zufluchtsuche?"}],"40:28":[{"t":"Allah schickt Hilfe aus Firʿawns eigener Sippe: einen Mann, der seinen Glauben verheimlichte. Er fragt: Wollt ihr einen Mann töten, nur weil er „Mein Herr ist Allah“ sagt?","q":"Und was wäre, falls Mūsā tatsächlich lügen sollte?"},{"t":"Dann schadet seine Lüge nur ihm selbst, und man muss dafür kein Blut vergießen. So argumentiert der Gläubige Schritt für Schritt mit der Vernunft.","q":"Und was droht ihnen, wenn Mūsā die Wahrheit sagt?"},{"t":"Dann trifft sie etwas von dem, was er ihnen androht. Wer einen wahrhaftigen Gesandten tötet, riskiert also die eigene Vernichtung.","q":"Mit welchem Grundsatz, der unverfänglich klingt, schließt er diesen Gedanken ab?"},{"t":"Allah leitet niemanden recht, der maßlos und verlogen ist. Für Firʿawn klingt das harmlos, doch gemeint ist er selbst als der Maßlose und Lügner.","q":"Was sagt er ihnen noch, damit sie sich nicht auf ihre Macht verlassen?"}],"40:29":[{"t":"Heute habt ihr die Herrschaft im Land, doch wer hilft uns, wenn Allahs Strafe kommt? Dann ist weltliche Macht bedeutungslos (vgl. Vers 16: „Wem gehört heute die Herrschaft?“).","q":"Was kann Firʿawn dieser Logik entgegensetzen?"},{"t":"Kein Argument, nur ein Machtwort: Er zeige ihnen nur, was er selbst sehe, und führe sie auf den rechten Weg. Das Volk soll ihm blind folgen.","q":"Lässt sich der Gläubige durch dieses Machtwort zum Schweigen bringen?"}],"40:30":[{"t":"Nein, er lässt sich nicht beirren und warnt: Ich fürchte für euch einen Tag wie den Tag der Gruppierungen. Der Begriff knüpft wörtlich an Vers 5 an.","q":"Wer waren diese Gruppierungen, an deren Schicksal er erinnert?"}],"40:31":[{"t":"Das Volk Nūḥs, ʿĀd, Ṯamūd und die nach ihnen. Mit ihrem Schicksal zeigt er, dass die Botschaft der Propheten über die Jahrhunderte dieselbe geblieben ist.","q":"War ihr Untergang eine willkürliche Härte Allahs?"},{"t":"Nein, Allah will kein Unrecht für Seine Diener. Ihr Untergang war die Folge ihrer eigenen Taten, ganz wie Vers 17 sagt: „Kein Unrecht gibt es heute.“","q":"Droht ihnen nur ein Untergang im Diesseits?"}],"40:32":[{"t":"Nein, er fürchtet für sie auch den Tag des gegenseitigen Rufens (Yawm at-Tanād), an dem die Menschen einander in Panik zurufen und die Engel die Sünder zur Abrechnung rufen.","q":"Können sie an diesem Tag irgendwohin entkommen?"}],"40:33":[{"t":"Nein, sie kehren den Rücken und fliehen, doch niemand schützt sie vor Allah. Wie schon in Vers 21 retten sie weder ihre Bauten noch ihre Herrschaft.","q":"Kann sie dann noch jemand auf den rechten Weg bringen?"},{"t":"Nein, wen Allah irregehen lässt, den kann niemand rechtleiten. Wer die Rechtleitung aus Hochmut ausschlägt, den überlässt Allah ﷻ seinem verdienten Irrtum.","q":"Gab es in der eigenen Geschichte Ägyptens schon ein Beispiel für diesen Irrweg?"}],"40:34":[{"t":"Ja: Nach ʿĀd und Ṯamūd nennt der Gläubige ein Beispiel aus Ägyptens eigener Geschichte. Yūsuf (Friede sei auf ihm) kam schon früher mit klaren Beweisen zu euch, doch ihr bliebt im Zweifel.","q":"Wie weit ging dieser Zweifel an Yūsufs Botschaft?"},{"t":"So weit, dass sie nach seinem Tod sagten, Allah werde nie wieder einen Gesandten schicken. Damit wollten sie sich nach al-Biqāʿī jeder moralischen Pflicht entledigen.","q":"Wen lässt Allah auf diese Weise irregehen?"},{"t":"So lässt Allah den irregehen, der maßlos (Isrāf) und voller Zweifel (Irtiyāb) ist. Wer beides verbindet, verschließt nach al-Biqāʿī sein eigenes Herz vor der Rechtleitung.","q":"Wer sind diese Maßlosen, die immer zweifeln?"}],"40:35":[{"t":"Es sind die, die über Allahs Zeichen streiten, ohne jeden Beweis (bi-ġayri sulṭān). Das ist das Hauptthema der Sure aus Vers 4, und ihr Streit beruht nur auf Einbildung und Vorurteil.","q":"Wie stehen Allah und die Gläubigen zu diesem Streit ohne Beweis?"},{"t":"Er erregt größten Abscheu (kabura maqtan), zuerst bei Allah ﷻ und auch bei den Gläubigen, deren gesunde Veranlagung von solcher Arroganz abgestoßen wird.","q":"Welche Folge hat diese Haltung für das Herz der Streitenden?"},{"t":"Als gerechte Folge versiegelt Allah das Herz jedes Hochmütigen (Mutakabbir) und Gewalttätigen (Ǧabbār). Ihr Wahrnehmungsorgan für die Wahrheit wird unbrauchbar.","q":"Wie zeigt sich dieses versiegelte Herz bei Firʿawn?"}],"40:36":[{"t":"Firʿawn hat den Argumenten des Gläubigen nichts mehr entgegenzusetzen und lenkt ab: O Hāmān, bau mir einen hohen Turm (Ṣarḥ), vielleicht erreiche ich die Zugänge.","q":"Welche Zugänge will Firʿawn mit diesem Turm erreichen?"}],"40:37":[{"t":"Die Zugänge der Himmel, um zu Mūsās Gott emporzuschauen. Er tut so, als prüfe er Mūsās Worte, gibt aber sogleich selbst zu: „Ich halte ihn für einen Lügner.“","q":"Warum sieht Firʿawn nicht, wie verkehrt sein eigenes Handeln ist?"},{"t":"Weil ihm sein böses Tun schön gemacht wurde: Allah lässt dem Hochmütigen seine schlechten Taten verlockend erscheinen, und so wurde Firʿawn vom rechten Weg abgehalten.","q":"Was wird am Ende aus Firʿawns List mit dem Turm?"},{"t":"Sie endet in nichts als Verlust (tabāb). Firʿawns ganze Taktik und List (Kayd) ist nach al-Biqāʿī von Grund auf zum Scheitern und Verderben verurteilt.","q":"Wie antwortet der Gläubige auf Firʿawns Anspruch, er führe das Volk den rechten Weg (Vers 29)?"}],"40:38":[{"t":"Er dreht Firʿawns Satz um: Folgt mir, so leite ich euch auf den Weg des rechten Handelns (Sabīl ar-Rašād). Nicht der Tyrann mit seinem Turm weist diesen Weg, sondern die göttliche Botschaft.","q":"Warum klammern sich Firʿawn und sein Volk so sehr an ihre Macht?"}],"40:39":[{"t":"Weil sie das Diesseits für die Endstation halten. Doch der Gläubige sagt: Dieses Leben ist nur ein kurzer Genuss (Matāʿ), und das Jenseits ist die bleibende Wohnstätte (Dār al-Qarār).","q":"Wie wird im Jenseits eine böse Tat vergolten?"}],"40:40":[{"t":"Nur mit ihresgleichen, nicht mehr (illā miṯlahā). Das ist nach al-Biqāʿī die absolute Gerechtigkeit: Eine Missetat wird genau nach ihrem Ausmaß vergolten.","q":"Und wie wird dagegen die gute Tat belohnt?"},{"t":"Wer gläubig ist und Gutes tut, ob Mann oder Frau, kommt ins Paradies und wird dort ohne Abrechnung versorgt. Das ist überfließende Barmherzigkeit, nicht an Rang, Reichtum oder Geschlecht gebunden.","q":"Wie fasst der Gläubige am Ende seine ganze Rede zusammen?"}],"40:41":[{"t":"Mit einem schmerzhaften Gegensatz: O mein Volk, ich rufe euch zur Rettung (an-Naǧāh), und ihr ruft mich zum Feuer! Er will ihre Rettung, sie wollen ihn ins Verderben ziehen.","q":"Wozu genau rufen sie ihn, wenn er vom Feuer spricht?"}],"40:42":[{"t":"Sie rufen ihn, Allah zu verleugnen und Ihm etwas beizugesellen, wovon er kein Wissen hat. So entlarvt er den Götzendienst als Behauptung ohne jedes Wissen.","q":"Und wozu ruft er sie im Gegensatz dazu?"},{"t":"Er ruft sie zum Allmächtigen (al-ʿAzīz), der vor jeder Tyrannei schützt, und zum Allvergebenden (al-Ġaffār). Das knüpft an den Anfang der Sure an (Vers 2–3).","q":"Welchen Wert hat das, wozu sie ihn rufen?"}],"40:43":[{"t":"Ganz sicher keinen (lā ǧarama): Ihre Götzen haben weder im Diesseits noch im Jenseits irgendeinen Anspruch oder eine Wirksamkeit.","q":"Wenn die Götzen nichts vermögen, zu wem führt dann am Ende die Rückkehr?"},{"t":"Die Rückkehr aller führt ausnahmslos zu Allah ﷻ. Die Götzen, zu denen sie ihn rufen, haben dort keinerlei Anspruch.","q":"Welche Menschen erwartet bei dieser Rückkehr das Feuer?"},{"t":"Die Maßlosen sind die Gefährten des Feuers. Damit schließt der Gläubige seine Beweisführung ab, obwohl er die Bedrohung durch die Versammelten spürt.","q":"Was kündigt er ihnen über seine Worte an, die sie jetzt ablehnen?"}],"40:44":[{"t":"Ihr werdet euch noch an meine Worte erinnern (fa-sataḏkurūn). Er weiß, dass sich die Wahrheit erst zu spät in ihren Verstand brennen wird.","q":"Was tut er selbst angesichts ihrer Bedrohung?"},{"t":"Er übergibt seine Angelegenheit ganz Allah (wa-ufawwiḍu amrī ilā-llāh). Das ist vollkommenes Gottvertrauen (Tafwīḍ): Er legt sein Schicksal restlos in Allahs Hand.","q":"Warum kann er sich so ganz auf Allah verlassen?"},{"t":"Weil Allah die Diener wohl sieht (Baṣīrun bil-ʿibād). Der Schöpfer verliert Seine Diener niemals aus den Augen, auch nicht diesen bedrohten Gläubigen.","q":"Wie antwortet Allah auf dieses Gottvertrauen?"}],"40:45":[{"t":"Sofort, wie das „Fa“ zeigt: Allah bewahrt ihn vor den Übeln ihrer Ränke und zerschlägt die Mordpläne des Hofstaates. Der Gläubige bleibt unversehrt.","q":"Und was trifft stattdessen Firʿawn und seine Leute?"},{"t":"Das Verderben wendet sich ganz gegen sie: Die schlimme Strafe umschließt die Sippe Firʿawns, die den Gläubigen mit ihren Ränken treffen wollte.","q":"Wie sieht diese Strafe schon vor dem Jüngsten Tag aus?"}],"40:46":[{"t":"Schon in der Zwischenwelt (Barzaḫ) werden sie morgens und abends dem Feuer vorgeführt. Nach al-Biqāʿī ist dies eines der stärksten Zeugnisse des Korans für die Strafe im Grab.","q":"Und was geschieht mit ihnen, wenn die Stunde kommt?"},{"t":"Dann heißt es: Lasst die Sippe Firʿawns in die strengste Strafe eingehen. Auf die Zwischenwelt folgt so die ultimative, ewige Pein (ašadd al-ʿaḏāb).","q":"Hört ihr Streiten selbst in der Hölle auf?"}],"40:47":[{"t":"Nein, sie streiten sogar im Feuer weiter, so endet das Streiten aus Vers 4. Die schwachen Mitläufer sagen zu den Hochmütigen: Wir waren eure Gefolgsleute.","q":"Was verlangen die Mitläufer nun von ihren einstigen Anführern?"},{"t":"Sie fragen: Könnt ihr uns nun einen Teil des Feuers abnehmen? Die weltliche Rangordnung zerbricht, und die Mitläufer verlangen vergeblich Entlastung.","q":"Was antworten die Hochmütigen darauf?"}],"40:48":[{"t":"Wir sind alle darin. Die einstigen Mächtigen, die sich auf Erden wie Firʿawn in Vers 29 für unantastbar hielten, bekennen ihre völlige Machtlosigkeit.","q":"Warum kann nun keiner dem anderen etwas von der Strafe abnehmen?"},{"t":"Weil Allah bereits zwischen den Dienern gerichtet hat. Sie verweisen selbst auf Sein unanfechtbares Urteil, was das Prinzip des absoluten Richtens aus Vers 12 und 20 bestätigt.","q":"An wen wenden sie sich, als auch untereinander keine Hilfe kommt?"}],"40:49":[{"t":"An die Wächter der Hölle: Ruft euren Herrn an, dass Er uns einen Tag die Strafe erleichtert. In Vers 11 wollten sie noch ganz hinaus, jetzt bitten sie nur um einen einzigen Tag.","q":"Was antworten die Wächter auf diese Bitte?"}],"40:50":[{"t":"Die Wächter antworten nicht mit Mitleid, sondern mit einer Gegenfrage: Kamen nicht eure Gesandten mit klaren Beweisen zu euch? So stellen sie die eigene Schuld der Verdammten fest.","q":"Können die Verdammten leugnen, dass die Gesandten mit klaren Beweisen zu ihnen kamen?"},{"t":"Nein, sie können nichts leugnen und sagen: „Doch!“ Mit diesem Eingeständnis, dass die Warnung da war, nehmen sie sich selbst jeden Anspruch auf Gnade.","q":"Was sagen die Wächter nach diesem Eingeständnis zu der Bitte der Verdammten?"},{"t":"Die Wächter sagen: „So ruft doch selbst!“ Das ist keine Einladung, sondern macht nur deutlich, dass es für die Verdammten keinen Ausweg mehr gibt.","q":"Hat das Rufen der Verdammten in der Hölle denn irgendeine Wirkung?"},{"t":"Nein, das Rufen der Ungläubigen geht ins Leere, wie ihre List in Vers 25. Wer im Diesseits mit List gegen die Zeichen kämpfte, dessen Bitten verhallen im Jenseits wirkungslos.","q":"Wenn die Feinde der Gesandten ohne Beistand bleiben, wie steht es dann um die Gesandten selbst?"}],"40:51":[{"t":"Allah steht Seinen Gesandten und den Gläubigen bei, im Diesseits und an dem Tag, an dem die Zeugen aufstehen. Dieser Beistand ist nach al-Biqāʿī ein unumstößliches Gesetz.","q":"Können sich die Ungerechten an diesem Tag noch mit einer Entschuldigung retten?"}],"40:52":[{"t":"Nein, an jenem Tag nützt den Ungerechten ihre Entschuldigung nichts. Für die Unterdrücker gibt es dann keine wirksame Entschuldigung mehr, ganz anders als für die Gesandten.","q":"Was erwartet die Ungerechten an jenem Tag statt der Barmherzigkeit?"},{"t":"Statt Barmherzigkeit trifft sie der Fluch, also die Verbannung aus Allahs Gnade, und ihnen gehört die böse Wohnstätte, die Wohnstätte der Erniedrigung.","q":"Gibt es ein Beispiel aus der Geschichte, dass Allah Seinem Gesandten wirklich beisteht?"}],"40:53":[{"t":"Ja, Mūsā: Allah rettete ihn trotz Pharaos Heeren und gab ihm die Rechtleitung, und die einst unterdrückten Kinder Isrāʾīls ließ Er die Schrift erben. So wird die Zusage aus Vers 51 greifbar.","q":"Wozu diente diese Schrift, die die Kinder Isrāʾīls erbten?"}],"40:54":[{"t":"Die Schrift war kein leeres Dokument, sondern Rechtleitung und Mahnung für die, die Verstand besitzen und aus den Gesetzen der Geschichte lernen.","q":"Wenn Allahs Beistand so sicher ist: Was soll der Prophet ﷺ gegenüber den Leugnern in Mekka tun?"}],"40:55":[{"t":"Du (der Prophet ﷺ) sollst geduldig sein, denn wie Mūsās Sieg zeigt, ist Allahs Versprechen wahr. Bitte um Vergebung und preise deinen Herrn abends und morgens, wie die Thronträger in Vers 7.","q":"Warum streiten die Leugner eigentlich ohne jeden Beweis über Allahs Zeichen?"}],"40:56":[{"t":"Nicht aus Suche nach Wahrheit, sondern weil in ihren Brüsten nur Hochmut ist, eine Größe, die sie nie erreichen. Damit kehrt die Sure zu ihrem Hauptthema aus Vers 4 und 35 zurück.","q":"Wie soll sich der Prophet ﷺ vor dem Hochmut und den Intrigen dieser Streitenden schützen?"},{"t":"Der Befehl an dich (den Propheten ﷺ) lautet: Nimm Zuflucht bei Allah, so wie Mūsā es in Vers 27 tat. Denn ihr Neid und Hochmut treibt sie zu Intrigen.","q":"Warum ist gerade Allah die sichere Zuflucht vor diesen Streitenden?"},{"t":"Weil Er der Allhörende ist, der ihr Reden hört, und der Allsehende, der ihre Machenschaften sieht.","q":"Wie wird dieser Hochmut der Streitenden zerschlagen?"}],"40:57":[{"t":"Durch den Blick auf den Kosmos: Die Erschaffung der Himmel und der Erde ist größer als die Erschaffung der Menschen. Doch die meisten überschätzen sich, weil ihnen wahres Wissen fehlt.","q":"Sind der, der diese Größe erkennt, und der, der sie nicht erkennt, gleich?"}],"40:58":[{"t":"Nein, der Blinde und der Sehende sind nicht gleich, ebenso wenig der Gläubige, der Gutes tut, und der hochmütige Übeltäter, weder im Wert noch im Ausgang.","q":"Wie viele Menschen denken über diese offensichtlichen Wahrheiten wirklich nach?"},{"t":"Nur wenige: „Wie wenig ihr bedenkt!“ Mit diesem Weckruf schließt die Seite, denn kaum jemand denkt über diese offensichtlichen Wahrheiten tiefgründig nach.","q":"Was folgt für die Auferstehung daraus, dass Allah das Größere, Himmel und Erde, erschaffen hat?"}],"40:59":[{"t":"Wer das Größere erschuf, kann die Menschen auch wiedererwecken: Die Stunde kommt ganz sicher. Doch die meisten Menschen glauben nicht, weil sie blind sind wie in Vers 58.","q":"Welchen Weg zur Rettung eröffnet Allah, wenn die Stunde so sicher kommt?"}],"40:60":[{"t":"Das Bittgebet: Euer Herr sagt „Ruft Mich an, so erhöre Ich euch“. Ohne Beistand wäre der Mensch der Stunde schutzlos ausgeliefert, darum öffnet Allah diesen Weg.","q":"Und was geschieht mit dem, der Ihn nicht anrufen will?"},{"t":"Wer sich aus Hochmut weigert, Ihm zu dienen, also Ihn zu bitten, geht erniedrigt in die Hölle ein. So wird der Hochmut aus Vers 56 bestraft, denn das Bittgebet ist das Mark des Gottesdienstes.","q":"Warum sollen wir gerade Ihn und keinen anderen anrufen?"}],"40:61":[{"t":"Weil Er für uns sorgt: Allah hat die Nacht gemacht, damit wir in ihr ruhen, und den Tag hell, als Raum für Tätigkeit und Lebensunterhalt.","q":"Danken die Menschen Allah für diese tägliche Ordnung von Nacht und Tag?"},{"t":"Die meisten nicht: Allah ist voll Huld gegen die Menschen, und Seine Huld ist überall. Doch die meisten Menschen verweigern Ihm den gebotenen Dank.","q":"Wer ist der, der euch so voller Huld Ruhe in der Nacht und Licht am Tag schenkt?"}],"40:62":[{"t":"Das ist Allah, euer Herr, der Schöpfer von allem. Wer Nacht, Tag und Himmel erschuf, ist Schöpfer aller Dinge, und daraus folgt: Es gibt keinen Gott außer Ihm.","q":"Was sagt Allah zu denen, die sich trotz dieser Beweise Götzen zuwenden?"},{"t":"Er fragt tadelnd: „Wie lasst ihr euch also abwenden?“ Es ist widersinnig, auf solche Gnadenbeweise mit Götzenkult zu antworten.","q":"Ist diese Abwendung von Allah etwas Neues?"}],"40:63":[{"t":"Nein, genauso ließen sich schon früher die abwenden, die Allahs Zeichen wissentlich leugneten, wie in Vers 5 und 21. Die Verblendung der Mekkaner ist keine Ausnahme.","q":"Welche Gaben zeigt Allah noch, nachdem Er Nacht und Tag genannt hat?"}],"40:64":[{"t":"Nach Zeit und Licht nun Raum und Mensch: die Erde als fester Grund, der Himmel als Bau, eure schöne Gestalt und die guten Dinge als Versorgung.","q":"Wer steht hinter dieser ganzen Ordnung von Erde, Himmel, Gestalt und Versorgung?"},{"t":"Das ist doch Allah, euer Herr, wie schon in Vers 62. Er, der euch Erde, Himmel, schöne Gestalt und gute Versorgung gab, ist euer Herr.","q":"Womit schließt Vers 64 angesichts dieser lückenlosen Gnadenordnung?"},{"t":"Mit dem erhabenen Lobpreis: Segensreich ist Allah, der Herr der Welten, überreich an Segen und Majestät ist der Erhalter aller Welten.","q":"Was folgt aus all diesen Gaben für die Menschen?"}],"40:65":[{"t":"Er ist der Lebendige, es gibt keinen Gott außer Ihm, also ruft Ihn aufrichtig an, wörtlich wie in Vers 14. Damit rundet sich das Gebot „Ruft Mich an“ aus Vers 60 ab.","q":"Mit welchen Worten schließt dieser Aufruf, Ihn aufrichtig anzurufen?"},{"t":"Mit dem Lob: Alles Lob gebührt Allah, dem Herrn der Welten. Er allein ist der Lebendige, während alle Götzen leblos oder sterblich sind.","q":"Was soll der Prophet ﷺ den Götzendienern deshalb klar sagen?"}],"40:66":[{"t":"Er soll die klare Trennlinie ziehen: Nach den klaren Beweisen ist ihm verboten, dem zu dienen, was sie neben Allah anrufen, und befohlen, sich dem Herrn der Welten zu ergeben.","q":"Welchen Beweis für Allah gibt es direkt im Menschen selbst?"}],"40:67":[{"t":"Seinen eigenen Werdegang: Nach den Zeichen im Kosmos führt Allah den Menschen zu seinem Ursprung zurück. Aus Erde, Samentropfen und Anhängsel wird er ein Kind, erreicht seine Vollkraft und wird ein Greis.","q":"Erreicht jeder Mensch diese Stufen bis ins hohe Alter?"},{"t":"Nein, manche von euch werden schon vorher abberufen. Niemand kann diesen Ablauf steuern oder aufhalten.","q":"Wozu lässt Allah den Menschen durch all diese Stufen gehen?"},{"t":"Damit jeder die festgesetzte Frist erreicht, die ihm bestimmt ist, und damit ihr begreift. Diese Frist zeigt, dass der Mensch vollkommen in der Hand seines Schöpfers liegt.","q":"Wer bestimmt allein über dieses Leben und Sterben?"}],"40:68":[{"t":"Er allein macht lebendig und lässt sterben. Nach al-Biqāʿī ist diese ausschließliche Macht über Leben und Tod die logische Krönung der beschriebenen Entwicklung.","q":"Braucht Er für so gewaltige Vorgänge Mühe oder Werkzeuge?"},{"t":"Nein, Er braucht weder Mühe noch Werkzeuge: Wenn Er etwas beschließt, sagt Er nur „Sei!“, und es ist. Ein einziger Befehl genügt.","q":"Wie kann jemand nach so klaren Beweisen im Kosmos und im eigenen Körper noch streiten?"}],"40:69":[{"t":"Das ist erstaunlich: Siehst du nicht die, die über Allahs Zeichen streiten, wie sie sich abwenden lassen? Damit kehrt das Hauptthema der Sure aus Vers 4, 35 und 56 zurück.","q":"Wer sind diese Streitenden genau?"}],"40:70":[{"t":"Es sind die, die das Buch und die Botschaft aller Gesandten der Lüge bezichtigen. Ihr Streit richtet sich gegen das Fundament: das Buch und die ganze Kette der Propheten.","q":"Was droht Allah ihnen für diese Leugnung an?"},{"t":"Sie werden es noch erfahren. Diese Drohung („fa-sawfa yaʿlamūn“) kündigt die schreckliche Wirklichkeit an, die sie jenseits des Schleiers erwartet.","q":"Was genau werden sie erfahren?"}],"40:71":[{"t":"Sie erfahren es, wenn Fesseln um ihre Hälse gelegt sind und sie an Ketten gezerrt werden. Der Hals, der sich nicht vor Allah beugen wollte (Vers 60), wird nun gefesselt.","q":"Wohin werden sie an diesen Ketten gezerrt?"}],"40:72":[{"t":"Erst ins siedende Wasser, dann werden sie im Feuer angezündet. Wie Vieh werden sie geschleift und dienen dem Höllenfeuer als Brennstoff.","q":"Was kommt zu dieser körperlichen Strafe noch hinzu?"}],"40:73":[{"t":"Hierauf die beschämende Frage: Wo ist das, was ihr beizugesellen pflegtet … Zur körperlichen Qual tritt nun die seelische Demütigung.","q":"Anstelle von wem dienten sie diesen Götzen?"}],"40:74":[{"t":"… anstatt Allahs? Die tadelnde Frage deckt auf, wie völlig nichtig alles ist, was sie neben Allah angebetet haben.","q":"Was antworten sie auf diese tadelnde Frage?"},{"t":"Sie sagen: Sie sind uns entschwunden, ja, eigentlich riefen wir früher gar nichts an. Ihre Götzen sind spurlos verschwunden.","q":"Was zeigt dieses Bekenntnis über den Weg der Ungläubigen?"},{"t":"So lässt Allah die Ungläubigen irregehen. Sie müssen bekennen, dass ihre ganze irdische Anbetung ein Dienst an reinen Nichtigkeiten war.","q":"Was war die Ursache für dieses Ende?"}],"40:75":[{"t":"Weil ihr auf der Erde zu Unrecht frohlocktet und übermütig wart. Al-Biqāʿī nennt beides: frevelhafte Freude am Falschen und grenzenlosen Übermut ohne Ehrfurcht vor dem Jenseits.","q":"Welche Folge haben diese falsche Freude und dieser Übermut?"}],"40:76":[{"t":"Als gerechte Folge öffnen sich für sie die Tore der Hölle: Tretet ein, um ewig darin zu bleiben.","q":"Wie beschreibt Allah diese Bleibe und ihre Bewohner?"},{"t":"Wie schlimm ist die Bleibe der Hochmütigen! Die Sure nennt wieder den Hochmut als Grundübel, wie in Vers 27, 35, 56 und 60.","q":"Was soll der Prophet ﷺ tun, solange die Leugner noch nicht bestraft sind?"}],"40:77":[{"t":"Er soll standhaft sein, denn Allahs Versprechen ist wahr. Nach den Höllenszenen wendet sich Allah wieder Seinem Gesandten ﷺ zu, wörtlich wie in Vers 55.","q":"Muss der Prophet ﷺ die Strafe der Leugner noch selbst erleben?"},{"t":"Nicht unbedingt: Ob Allah dich (den Propheten ﷺ) einen Teil ihrer Strafe noch sehen lässt oder vorher abberuft, ändert nichts. Zu Ihm werden sie alle zurückgebracht.","q":"Ging es früheren Gesandten genauso?"}],"40:78":[{"t":"Ja, Allah sandte schon vor dir (dem Propheten ﷺ) viele Gesandte. Von manchen hat Er dir berichtet, von anderen nicht.","q":"Konnten diese Gesandten Wunder bringen, wann immer man es von ihnen verlangte?"},{"t":"Nein, kein Gesandter konnte ein Zeichen bringen außer mit Allahs Erlaubnis. So antwortet Allah den Leugnern, die Wunder forderten: Der Gesandte überbringt die Zeichen, er bewirkt sie nicht.","q":"Was geschieht, wenn die Zeit der Entscheidung schließlich gekommen ist?"},{"t":"Wenn Allahs Befehl kommt, wird mit der Wahrheit entschieden (wie in Vers 20), und dort verlieren die Verfechter des Falschen. Ihr Streit endet im Ruin.","q":"Die Leugner fordern Wunder, aber sehen sie nicht die Zeichen, die sie jeden Tag haben?"}],"40:79":[{"t":"Allah lenkt ihren Blick auf das Vieh: Er hat es euch gemacht, damit ihr auf einem Teil davon reitet und von einem Teil esst. Davon hängt euer Leben täglich ab.","q":"Welchen Nutzen haben die Menschen noch von diesem Vieh?"}],"40:80":[{"t":"Vielerlei Nutzen: Auf ihnen erreicht ihr die Ziele, die ihr euch vornehmt, und auf ihnen und auf Schiffen werdet ihr getragen. So verbindet Allah Land und Meer.","q":"Was folgt aus all diesen Zeichen, die sie täglich umgeben?"}],"40:81":[{"t":"Er zeigt euch ständig Seine Zeichen, welche davon wollt ihr denn leugnen? Diese Frage entlarvt ihren Streit als Verleugnung ohne jede sachliche Grundlage.","q":"Und wenn sie trotzdem leugnen: Was lehrt sie die Geschichte?"}],"40:82":[{"t":"Sie sollen auf der Erde umherreisen und das Ende der Völker vor ihnen betrachten. Fast wortgleich greift das Vers 21 wieder auf.","q":"Waren diese früheren Völker etwa schwächer als die heutigen Leugner?"},{"t":"Nein, sie waren zahlreicher, stärker und hinterließen mehr Spuren auf der Erde. Doch nichts, was sie anhäuften, schützte sie vor Allahs Urteil.","q":"Warum lehnten diese Völker ihre Gesandten dennoch ab?"}],"40:83":[{"t":"Weil sie sich über ihr eigenes weltliches Wissen freuten und meinten, die Offenbarung nicht zu brauchen. Doch genau das, worüber sie spotteten, umschloss sie am Ende.","q":"Was sagten sie, als Allahs Strenge dann vor ihren Augen stand?"}],"40:84":[{"t":"Plötzlich sagten sie: Wir glauben an Allah allein und verleugnen, was wir Ihm beigesellt haben. Das ist genau das Gegenteil von dem, was sie früher taten (Vers 12).","q":"Hat ihnen dieser späte Glaube noch genützt?"}],"40:85":[{"t":"Nein, ihr Glaube nützte ihnen nichts mehr, als sie Allahs Strenge schon sahen. Glaube hat nur Wert, solange er auf freier Entscheidung und dem Anerkennen des Verborgenen beruht.","q":"Warum machte Allah bei ihnen keine Ausnahme?"},{"t":"Das ist Allahs feste Gesetzmäßigkeit (Sunnatallāh), die schon an Seinen Dienern vollzogen wurde: Bricht die Strafe herein, ist eine Umkehr nicht mehr gültig.","q":"Wie endet es für die Ungläubigen in diesem Moment?"},{"t":"Dort sind die Ungläubigen verloren, wie am Schluss von Vers 78. Die Sure begann mit dem „Vergeber der Sünde, Annehmer der Reue“ (Vers 3) und endet mit einer Umkehr, die zu spät kommt.","q":""}]}};
